import{z as p,x as n,o,c as s,q as l,j as E,D as a,d as r,s as d,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Decode 侧 Expert Parallel","description":"","frontmatter":{"title":"Decode 侧 Expert Parallel","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-parallel-decode.md","filePath":"llm/expert-parallel-decode.md","lastUpdated":1791413859000}'),c={name:"llm/expert-parallel-decode.md"};function B(A,e,P,h,D,m){const t=n("Mermaid");return o(),s("div",null,[e[2]||(e[2]=l('<h1 id="decode-侧-expert-parallel" tabindex="-1">Decode 侧 Expert Parallel <a class="header-anchor" href="#decode-侧-expert-parallel" aria-label="Permalink to &quot;Decode 侧 Expert Parallel&quot;">​</a></h1><div class="epigraph"><p>解码最小单元为 40 节点 320 GPU；MoE 走 EP320，每卡一个专家，分发与合并用 IB 点对点，并借助 IBGDA 压延迟。</p><footer>—— DeepSeek-AI，DeepSeek-V3 技术报告部署节，arXiv:2412.19437，2024</footer></div><p>训练和预填的专家并行，batch 里有足够多的 token，All-to-All 的 payload 能盖住启动开销，GEMM 也接近计算墙。自回归 decode 每步每个请求只追加一个 token，即使连续批把并发堆起来，每专家的 \\(M\\) 仍常常落在「几百以下」。DeepSeek-V3 写过解码时每专家 batch 通常 <strong>不超过 256 token</strong>，瓶颈是访存不是算力。把训练拓扑（EP32、每卡多专家、分层 IB+NVLink）原样搬到逐步生成，会为几十字节的激活付一次集合通信的尾延迟。Decode 侧 EP 要单独设计：更宽的并行度、更少的每卡专家、点对点而不是大集体、以及和注意力重叠的调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Decode 的工作集是「本步所有请求的一个新 token」加整段 KV。MoE 还要加上专家权重。若把 256 个路由专家复制到每张生成卡，HBM 先被专家库吃光，KV 与并发没地方；若仍用小 EP、每卡很多专家，则每张卡每步都要扫过许多未被选中的专家权重——稀疏的意义只剩下「没算 FLOPs」，带宽账与稠密 FFN 接近。EP 的价值在 decode 上首先是 <strong>每卡只驻留少量专家，权重流量按 \\(1/E\\) 降</strong>，其次才是算力分摊。</p><p><span class="marginnote">直觉类比：预填像一次搬一整车货（\\(T\\) 很大），走整车集合运输划算；解码像每步只寄一封小信（\\(T\\) 等于在活请求数），为每封信包一架货机（集合通信启动）太贵——所以改用「点对点快递」（IB 点对点 + IBGDA），只求单件快，不求整车满。</span></p><p>通信形态却变差。预填 \\(T\\) 大，dispatch 的 \\(\\mathrm{bytes}\\propto kTd/E\\) 可观；decode 的 \\(T\\) 等于当前 batch 里的活请求数，往往只有几十到几百。NCCL All-to-All 的启动延迟、跨节点的握手，会高过 GEMM。V3 因此在解码阶段改用 <strong>直接点对点 IB</strong>，并启用 IBGDA（GPU 直接发起 RDMA，少绕主机），目标是逐步延迟而不是峰值带宽利用率。</p><h3 id="共享专家在解码里变成第九个必选专家" tabindex="-1">共享专家在解码里变成第九个必选专家 <a class="header-anchor" href="#共享专家在解码里变成第九个必选专家" aria-label="Permalink to &quot;共享专家在解码里变成第九个必选专家&quot;">​</a></h3><p>V3 把共享专家在解码时视为「永远被选中的重负载路由专家」，于是每 token 选 9 个专家。共享支路不再是「每卡本地一份、不算进 EP」的旁路，而要占物理槽位、进 EPLB 的负载向量。若实现仍在每张卡上复制共享专家，EP 的显存账又涨回去一块；若只放在少数卡上，所有 token 都要额外打到那些卡，它们成为永久热点。64 张卡专门承载冗余专家与共享专家，就是为这个结构付的固定税。</p><p><span class="marginnote">Mixtral 8 专家、top-2 的 decode 常常整模型 TP 或专家全复制，因为 \\(N=8\\) 放得下，逐步 All-to-All 不值得。本篇的对象是 DeepSeek-V3 / R1 这一类 \\(N\\) 到百、必须 EP 才能把权重铺开的解码。不要用 8 专家的延迟曲线外推 EP320。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>V3 公开的解码最小部署单元：</p><ul><li>40 节点 × 8 GPU = 320 GPU。</li><li>注意力：TP4 + 序列并行，再叠 DP80。</li><li>MoE：EP320。每卡一个专家；64 卡放冗余专家与共享专家。</li><li>Dispatch / combine：IB 上的点对点，而不是训练时「IB 到同号 GPU 再 NVLink 转发」的两跳集体。</li></ul><p>每卡一个专家使本地 MoE 变成「只加载一份 FFN」。V3 明确写：内存访问开销很小，即使用较少 SM 跑 dispatch+MoE+combine，也不怎么伤这段；注意力才是 decode 时间的大头。于是调度改成：两个计算量相近的 microbatch，一个在做注意力，另一个在做 dispatch+MoE+combine，并且后者只分到少量 SM，以免抢注意力的带宽。</p>',14)),(o(),E(i,null,{default:a(()=>[d(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20B0%5B%22microbatch%200%20%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20W0%5B%22%E7%AD%89%20batch%201%20%E7%9A%84%20MoE%22%5D%0A%20%20B1%5B%22microbatch%201%20dispatch%2BMoE%2Bcombine%22%5D%20--%3E%20W1%5B%22%E7%AD%89%20batch%200%20%E7%9A%84%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20W0%20--%3E%20NX%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%22%5D%0A%20%20W1%20--%3E%20NX%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l('<h3 id="通信后端从集合改成点对点" tabindex="-1">通信后端从集合改成点对点 <a class="header-anchor" href="#通信后端从集合改成点对点" aria-label="Permalink to &quot;通信后端从集合改成点对点&quot;">​</a></h3><p>训练 / 预填：token 先 IB 到目标节点同号 GPU，再 NVLink 转发，warp 分工，吃的是带宽，SM 占用约 20 个里划出通信通道。解码：目的 rank 由「每卡一个专家」直接决定，路径是 GPU 到 GPU 的 RDMA。IBGDA 让 GPU 自己发描述符，减少 CPU 参与的 doorbell。延迟的主导项变成 HCA 往返与小消息速率，而不是 GB/s。实现若仍调用一次全局 <code>alltoall_v</code>，内部可能仍按全连接握手，对 \\(E=320\\) 的小消息极不友好。</p><p>EPLB 在解码侧仍然周期更新冗余集合，但「每卡一个专家」意味着重平衡是换整卡的身份，而不是在卡内重排 8+1 个专家。动态冗余（每卡多驻留、每步只激活一部分）在解码里被报告写成「仍在探索」，因为选哪一份副本必须和 dispatch 核融合，否则每步的路由优化本身就拉高 TPOT。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Decode 侧 EP 的屋顶线与预填相反。专家 GEMM 的算术强度约为 \\(O(d_{\\mathrm{ff}})\\) 量级的一次矩阵-向量（\\(M\\) 小则接近 GEMV）。HBM 上扫一份专家权重大约是 \\(2\\cdot d\\cdot d_{\\mathrm{ff}}\\) 个元素（SwiGLU 再加倍）。EP 度升高，每卡扫的权重下降，这才是 decode 加速的主因。通信每 token 每层大约 \\(2k\\) 次发送（去程 \\(k\\)、回程 \\(k\\)），消息大小 \\(d\\cdot s\\) 字节。\\(d=7168\\)、BF16 时一条激活大约 14 KB，相对一次集合启动并不大，所以 <strong>消息速率和尾延迟</strong> 决定 TPOT。</p>',5)),(o(),E(i,null,{default:a(()=>[d(t,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22%E6%9C%AC%E6%AD%A5%E7%9A%84%E4%B8%80%E4%B8%AA%20token%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%E9%80%89%E5%87%BA%209%20%E4%B8%AA%E4%B8%93%E5%AE%B6%EF%BC%88%E5%90%AB%E5%85%B1%E4%BA%AB%EF%BC%89%22%5D%0A%20%20R%20--%3E%20S%5B%22P2P%20%E5%8F%91%E5%BE%80%E5%90%84%E4%B8%93%E5%AE%B6%E6%89%80%E5%9C%A8%E5%8D%A1%EF%BC%88%E5%8F%AF%E8%83%BD%E8%B7%A8%E8%8A%82%E7%82%B9%EF%BC%89%22%5D%0A%20%20S%20--%3E%20G%5B%22%E5%90%84%E5%8D%A1%E5%8F%AA%E6%89%AB%E6%9C%AC%E5%8D%A1%E4%B8%80%E4%BB%BD%E4%B8%93%E5%AE%B6%E6%9D%83%E9%87%8D%E5%81%9A%20GEMV%22%5D%0A%20%20G%20--%3E%20C%5B%22combine%20%E5%9B%9E%E4%BC%A0%E5%B9%B6%E5%8A%A0%E6%9D%83%E6%B1%82%E5%92%8C%22%5D%0A%20%20C%20--%3E%20N%5B%22%E4%BA%A4%E7%BB%99%E4%B8%8B%E4%B8%80%E6%AD%A5%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l('<p><span class="marginnote">数字实例：V3 每层 256 个路由专家，若每张生成卡都装全套，仅专家权重就占满 HBM，KV 缓存无处可放；EP320 摊下来每卡只驻留约 1 个专家，每步扫的权重字节也降到约 \\(1/320\\)——这才是解码侧 EP 要「宽」的真正动机：显存放得下、带宽扫得少。</span></p><p>注意力与 MoE 的时间比也翻转。预填注意力是 \\(O(s^2)\\) 量级的大 GEMM，MoE 也有大 \\(M\\)；解码注意力是读 KV 的带宽墙，MoE 是读专家权重的带宽墙。V3 说注意力占比更大，因此重叠时把 SM 留给注意力。若实现把 80% SM 绑在 MoE 通信核上，会得到「EP 很忙、生成反而更慢」。</p><p><span class="marginnote">MLA 压缩的是 KV 字节，不压缩专家权重。Decode EP 解决的是 MoE 参数铺不开、逐步通信延迟大；MLA 解决的是长生成时缓存铺不开。两者同时出现在 V3 的服务栈里，分母不同，不要合成一个「5.76×」。</span></p><h3 id="连续批、pd-分离与-ep-度" tabindex="-1">连续批、PD 分离与 EP 度 <a class="header-anchor" href="#连续批、pd-分离与-ep-度" aria-label="Permalink to &quot;连续批、PD 分离与 EP 度&quot;">​</a></h3><p>连续批把不同请求的 decode 步拼成一个小 batch，是让每专家 \\(M\\) 离开 1 的主要手段。但拼得越大，尾延迟越差：快请求要等慢请求的 MoE 通信。PD 分离让预填走 EP32 一类「算得满」的拓扑，解码走 EP320 一类「权重大、消息小」的拓扑，避免同一次 All-to-All 服务两种屋顶线。EPLB 的放置也因此分成两套：预填用层次装箱，解码用全局复制。把预填卡临时拿来跑 decode，EP 度与每卡专家数都不对，热专家会立刻露出来。</p><p>设备限制路由在解码仍有意义：一个 token 去太多节点，点对点连接数上升。V3 训练有「最多 4 节点」；解码每卡一专家时，9 个专家可能落在 9 个节点上，这是延迟预算必须包含的 hop 数。冗余专家的价值之一是让热点逻辑专家在拓扑上有多个落点，dispatch 可以选「更近或更空」的副本。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 \\(E\\) 很大时假设 NCCL 默认 All-to-All 与 IBGDA 点对点等价。前者为训练吞吐调过，后者为小消息延迟调过。基准必须报 TPOT 分位数，而不是只报 tokens/s。单请求 \\(M=1\\) 的延迟不能用满 batch 吞吐反推。</p><p><span class="marginnote">常见误区：以为开一个「EP 模式」开关就能拿到 EP320 的延迟。若通信仍走为吞吐调优的集合通信，对 320 张卡的小消息会被握手延迟吃光收益；基准要看 TPOT 分位数（如 P99），只看平均 tokens/s 会把尾延迟藏在平均值里。</span></p><p>每卡一个专家使故障域变细：一张卡坏了，某个逻辑专家（若无副本）直接消失。冗余 64 卡是可用性，不只是均衡。检查点恢复、滚动升级都要先保证逻辑专家的覆盖，再谈负载。</p><p>小集群复制不了 320 路 EP。降 EP、每卡多专家，decode 会回到「扫多份权重」的带宽墙，这是硬件规模问题，不是把 IBGDA 开关打开就能假装 EP320。Mixtral 类小 \\(N\\) 继续用 TP 或复制，是正确的工作点选择。</p><p><span class="marginnote">出处以 V3 报告第 3 节部署为准。开源框架里的 EP decode 是后续工程（vLLM、SGLang、TensorRT-LLM），通信后端名字会变，但合同仍是：小 \\(M\\)、宽 EP、点对点、与注意力重叠。不要把 DualPipe 训练重叠写成解码重叠——microbatch 的切法不同。</span></p><p>量化改变账本：专家走 NVFP4 后权重流量再降一档，EP 度可以略减仍放得下，但 dispatch 的激活若仍是 BF16，通信侧几乎不降。要对齐「权重精度」和「激活精度」，否则优化只发生在 GEMV，不发生在 IB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Decode 侧 EP 的主收益是每卡少驻留专家、降低逐步扫权重的字节，而不是把 GEMM 做满。</li><li>小 \\(M\\) 使集合通信的启动延迟不可接受；V3 用 EP320 + IB 点对点 + IBGDA。</li><li>注意力与 dispatch+MoE 分 microbatch 重叠，MoE 只占少量 SM。</li><li>共享专家按必选重负载专家占槽位；冗余卡同时服务均衡与容错。</li><li>连续批和 PD 分离是让两种屋顶线分开的调度，不是 EP 公式的一部分。</li><li>出处：DeepSeek-AI，<em>DeepSeek-V3</em>，arXiv:2412.19437；NVIDIA IBGDA 文档；Lepikhin <em>GShard</em> / Fedus <em>Switch</em> 作为 EP 语义对照。</li></ul>',15))])}const k=p(c,[["render",B]]);export{_ as __pageData,k as default};
